import {scenes,categories,slots,helpPhrases} from './data.js';
import {cleanPhrasebook,resolveScene} from './model.js';
import {particleText as text,plainJapanese} from '../particles/ui.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function pocketScenes(book){const safe=cleanPhrasebook(book);return safe.saved.map(id=>resolveScene(scenes.find(s=>s.id===id),safe.selections[id]||{}));}
export function selectionSummary(scene,book){return scene.slots.map(key=>{const field=slots[key],option=field.options.find(o=>o.id===book.selections?.[scene.id]?.[key])||field.options[0];return option.zh.startsWith(field.label)?option.zh:`${field.label}：${option.zh}`;}).join(' · ');}
export function pocketText(book){
 const sections=pocketScenes(book).map(s=>[s.title,selectionSummary(s,book),...s.lines.map(l=>`${l.role==='you'?'你可以說':'對方常說'}：${plainJapanese(l.jp)}\n${l.zh}`),...s.alternatives.map(l=>`${l.label}：${plainJapanese(l.jp)}\n${l.zh}`),s.note].filter(Boolean).join('\n\n'));
 return '\uFEFF我的旅行會話小抄｜日和日語\n\n'+sections.join('\n\n──────────\n\n')+'\n\n聽不懂時的求助語\n\n'+helpPhrases.map(h=>`${plainJapanese(h.jp)}\n${h.zh}`).join('\n\n')+'\n\n回覆與現場資訊為會話示例，實際內容請向對方確認。';
}
export function pocketHtml(book){
 const saved=pocketScenes(book),line=l=>`<div class="line ${l.role}"><small>${l.role==='you'?'你可以說':'對方常說'}</small><p lang="ja">${text(l.jp)}</p><p>${esc(l.zh)}</p></div>`;
 return `<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><title>我的旅行會話小抄｜日和日語</title><style>body{margin:0;background:#f7f8f1;color:#385640;font:16px/1.9 system-ui,sans-serif}main{max-width:850px;margin:auto;padding:30px 22px}h1{font-size:30px}h2{font-size:23px;margin:0 0 12px}article,.help{background:#fffef9;border:1px solid #d8e0cb;border-radius:12px;padding:25px;margin:25px 0}.note,small{font-size:13px;color:#5f7056}.line{padding:14px 17px;background:#edf2e3;border-radius:8px;margin:14px 0}.staff{background:#f3efe5}p[lang=ja]{font-family:serif;font-size:25px;line-height:2.2;overflow-wrap:anywhere;margin:10px 0}.line>p:last-child{margin:6px 0}ruby rt{font-size:.5em}summary{cursor:pointer;font-size:16px;padding:10px 0}details{margin-top:17px}.meta{font-size:13px;color:#6a795f}footer{font-size:13px;margin:30px 0}.help p{margin:5px 0 20px}@media(max-width:450px){main{padding:20px 14px}article,.help{padding:20px 16px}h1{font-size:25px}p[lang=ja]{font-size:23px}}@media print{@page{margin:15mm}body{background:white;color:black;font-size:12pt}main{max-width:none;padding:0}article,.help{border:1px solid #aaa;break-inside:avoid}p[lang=ja]{font-size:19pt}.note{color:#444}details{display:block}details>*{display:block}.meta,small{color:#444}}</style></head><body><main><header><p>HIYORI JAPANESE · TRAVEL POCKET PHRASES</p><h1>我的旅行會話小抄</h1><p>${saved.length} 個收藏情境，已套用你選擇的地點、數量等內容。</p><p class="note">此檔的日文、中文與振假名可離線閱讀，不需要連線載入素材。語音請回網站播放。也可使用瀏覽器的列印功能保存PDF。</p></header>${saved.map(s=>`<article><p class="meta">${esc(categories.find(c=>c.id===s.category).name)}</p><h2>${esc(s.title)}</h2>${s.slots.length?`<p class="meta">${esc(selectionSummary(s,book))}</p>`:''}${s.lines.filter(l=>l.role==='you').map(line).join('')}<details><summary>對方可能說的話與其他說法</summary>${s.lines.filter(l=>l.role==='staff').map(line).join('')}${s.alternatives.map(l=>`<p class="meta">${esc(l.label)}</p>${line(l)}`).join('')}</details>${s.note?`<p class="note">${esc(s.note)}</p>`:''}</article>`).join('')}<section class="help"><h2>聽不懂時，先用這幾句</h2>${helpPhrases.map(h=>`<p lang="ja">${text(h.jp)}</p><p>${esc(h.zh)}</p>`).join('')}</section><footer>來源：日和日語「日常會話」。對方的回覆是示例，現場資訊與規定請向對方確認。</footer></main></body></html>`;
}
